174: /// The deletion transaction recorded in `dir`, if any (`None` also for a record that does not
175: /// parse - [`deletion_state`] counts that one as pending).
176: pub fn pending_deletion_in(dir: &Path) -> Option<PendingDeletion> {
177:     let text = fs::read_to_string(dir.join(FORGET_PENDING)).ok()?;
178:     serde_json::from_str(&text).ok()
179: }
180: 
181: /// What the deletion transaction asks of a producer and of the sender.
182: pub(crate) enum DeletionState {
183:     /// No transaction: spool and send.
184:     None,
185:     /// Pending at the intake - or a record that cannot be read (fail closed): spool nothing, send
186:     /// nothing.
187:     Pending,
188:     /// Confirmed (or local-only), the local cleanup not finished: spool nothing, send nothing; the
189:     /// sender finishes the cleanup with this record's identity.
190:     Cleanup(PendingDeletion),
191: }
192: 
193: /// The deletion state of `dir`. Decisions are taken on it under the sender lock and the spool lock
194: /// (F09-2); every write of the record holds both.
195: pub(crate) fn deletion_state(dir: &Path) -> DeletionState {
196:     match fs::read_to_string(dir.join(FORGET_PENDING)) {
197:         Err(e) if e.kind() == std::io::ErrorKind::NotFound => DeletionState::None,
198:         Err(_) => DeletionState::Pending,
199:         Ok(t) => match serde_json::from_str::<PendingDeletion>(&t) {
200:             Ok(r) if r.cleanup_due() => DeletionState::Cleanup(r),
201:             _ => DeletionState::Pending,
202:         },
203:     }
204: }
205: 
206: /// Write the transaction record (atomically). The caller holds the sender lock and the spool lock.
207: fn write_transaction(dir: &Path, record: &PendingDeletion) -> Result<()> {
208:     fs::create_dir_all(dir)?;
209:     let text = serde_json::to_string_pretty(record)?;
210:     replace_atomic(&dir.join(FORGET_PENDING), text.as_bytes())
211: }
