213: /// What a local cleanup removed, and where it stopped.
214: #[derive(Debug, Default)]
215: pub(crate) struct Cleanup {
216:     /// The files removed, in order.
217:     pub removed: Vec<String>,
218:     /// A salt that names another instance (made after the deletion began): kept, said here.
219:     pub kept: Option<String>,
220:     /// Why the cleanup stopped (`None`: it finished - with `own_record`, the record is gone).
221:     pub error: Option<String>,
222: }
223: 
224: /// The local cleanup of the instance `txn` names, run while the caller holds the sender lock and
225: /// the spool lock (F09-3). The QUEUED data goes first - the spool, a rewrite's leftover temporary
226: /// copies, the not-spooled counts, the last flush -, then the proof (the references), the identity
227: /// (the salt) LAST, and only when it is still `txn`'s instance (a salt made after the deletion began
228: /// is another instance and stays). `own_record`: the transaction is this cleanup's (confirmed, or a
229: /// local-only deletion) - it is set to `cleaning` before the first removal and removed after the
230: /// last, so an interruption leaves a record that blocks spooling and sending and that the next flush
231: /// or forget resumes (a `cleaning` `txn` is on disk already: a resumed cleanup's, or a local-only
232: /// deletion's, which its forget records before calling here - F14-1); `false`: a PENDING
233: /// deletion's record (the retry's identity) is left as it is.
234: /// `remove` removes one file (tests inject a failure).
235: pub(crate) fn run_local_cleanup(
236:     dir: &Path,
237:     txn: &PendingDeletion,
238:     own_record: bool,
239:     remove: &dyn Fn(&Path) -> std::io::Result<()>,
240: ) -> Cleanup {
241:     let mut c = Cleanup::default();
