243:         let mut cleaning = txn.clone();
244:         cleaning.phase = PHASE_CLEANING.to_string();
245:         if let Err(e) = write_transaction(dir, &cleaning) {
246:             c.error = Some(format!(
247:                 "the deletion record could not be moved to cleaning ({e})"
248:             ));
249:             return c;
250:         }
251:     }
252:     let mut targets: Vec<PathBuf> = vec![dir.join(SPOOL_FILE)];
253:     // a rewrite that died before its rename left a temporary copy of the spool beside it
254:     let spool_tmp = format!(".{SPOOL_FILE}.");
