272:     );
273:     for p in targets {
274:         if !p.exists() {
275:             continue;
276:         }
277:         if let Err(e) = remove(&p) {
278:             c.error = Some(format!(
279:                 "{}: {}",
280:                 p.display(),
281:                 c3_core::one_line(&e.to_string())
282:             ));
283:             return c;
284:         }
285:         c.removed.push(
286:             p.file_name()
287:                 .and_then(|n| n.to_str())
288:                 .unwrap_or("?")
