297:                 c.error = Some(format!(
298:                     "{}: {}",
299:                     salt.display(),
300:                     c3_core::one_line(&e.to_string())
301:                 ));
302:                 return c;
303:             }
304:             c.removed.push("salt".to_string());
305:         } else {
306:             c.kept = Some(format!(
307:                 "the salt names another instance ({}) made after the deletion of {} began: kept",
308:                 if current.is_empty() {
309:                     "unreadable"
310:                 } else {
311:                     current.as_str()
312:                 },
313:                 if txn.instance_id.is_empty() {
314:                     "this machine's data"
315:                 } else {
316:                     txn.instance_id.as_str()
359:         let why = serde_json::from_str::<Value>(&body)
360:             .ok()
361:             .and_then(|v| v.get("error").and_then(|e| e.as_str()).map(str::to_string))
362:             .filter(|s| !s.is_empty());
363:         match why {
364:             Some(w) => format!("HTTP {code}: {}", c3_core::one_line(&w)),
365:             None => format!("HTTP {code}"),
366:         }
367:     };
368:     match agent.request("DELETE", &url).call() {
369:         Ok(resp) => {
370:             let code = resp.status();
371:             let body = resp.into_string().unwrap_or_default();
372:             match serde_json::from_str::<Value>(&body) {
373:                 Ok(v) if v.get("ok") == Some(&Value::Bool(false)) => Err(err_of(code, body)),
374:                 _ => Ok(()),
375:             }
376:         }
377:         Err(ureq::Error::Status(code, resp)) => {
378:             Err(err_of(code, resp.into_string().unwrap_or_default()))
