387: /// Forget with the default hub and directory ([`forget_at`]).
388: pub fn forget(req: &ForgetRequest, confirm: impl Fn(&str) -> bool) -> ForgetOutcome {
389:     forget_at(&crate::telemetry::hub(), &telemetry_dir(), req, confirm)
390: }
391: 
392: /// `Invoke-TelemetryForget` with C3's deletion transaction (F02-3, F09-2, F09-3): with a public
393: /// reference the intake is asked FIRST to delete every event and complaint of this instance; a
394: /// DELETE the intake does not confirm deletes NOTHING here (the salt, the spool, the references
395: /// stay) and leaves the transaction `pending` - the instance id and the reference a retry needs -
396: /// in `forget-pending.json`, which freezes telemetry (nothing spooled or sent) until a retry is
397: /// confirmed. `local` removes the local files only after a confirmed DELETE (or, without a
398: /// reference, after the user confirmed a local-only deletion through `confirm`). A transaction
399: /// whose cleanup did not finish is finished first. `hub`: the resolved intake.
400: ///
401: /// Every forget holds the sender lock and the spool lock from its first write of the transaction
402: /// to its last (F09-2): the record is written BEFORE the DELETE, so a sender never passes its check
403: /// while a deletion is under way and a crash during the DELETE leaves a pending deletion (F09-3).
404: pub fn forget_at(
405:     hub: &crate::telemetry::Hub,
406:     dir: &Path,
407:     req: &ForgetRequest,
408:     confirm: impl Fn(&str) -> bool,
409: ) -> ForgetOutcome {
410:     forget_with(hub, dir, req, confirm, &|p| fs::remove_file(p))
411: }
412: 
413: /// [`forget_at`] with an injected file removal (tests interrupt the local cleanup with it).
414: #[doc(hidden)]
415: pub fn forget_with(
416:     hub: &crate::telemetry::Hub,
417:     dir: &Path,
418:     req: &ForgetRequest,
419:     confirm: impl Fn(&str) -> bool,
420:     remove: &dyn Fn(&Path) -> std::io::Result<()>,
421: ) -> ForgetOutcome {
422:     const P: &str = "codex-telemetry";
423:     let mut out = ForgetOutcome::default();
424:     // read without the locks for the request's checks and the question; decided again under them
425:     let seen = pending_deletion_in(dir);
426:     let resume = seen.as_ref().is_some_and(|p| p.cleanup_due());
427:     let explicit = req
428:         .public_ref
429:         .as_deref()
430:         .map(str::trim)
431:         .filter(|r| !r.is_empty())
432:         .map(str::to_string);
433:     let pending_ref = |p: &Option<PendingDeletion>| {
434:         p.as_ref()
435:             .filter(|p| p.phase == PHASE_PENDING && !p.public_ref.is_empty())
436:             .map(|p| p.public_ref.clone())
437:     };
438:     let reference = explicit.clone().or_else(|| pending_ref(&seen));
439:     let nothing = if req.local {
440:         "nothing was sent and nothing removed"
441:     } else {
442:         "nothing was sent"
443:     };
444:     if !resume {
445:         if reference.is_none() && !req.local {
446:             out.exit = 1;
447:             out.lines.push(format!("{P}: -Forget needs -PublicRef <ref> (delete the data of this instance at the intake), -Local (remove the local spool and the salt), or both."));
448:             return out;
449:         }
450:         if let Some(r) = &reference {
451:             if !is_public_ref(r) {
452:                 out.exit = 1;
453:                 out.lines.push(format!("{P}: -PublicRef '{r}' is not a public_ref (letters, digits, dot, dash, underscore); {nothing}."));
454:                 return out;
455:             }
456:             if !hub.error.is_empty() {
457:                 out.exit = 1;
458:                 out.lines.push(format!("{P}: {}; {nothing}.", hub.error));
459:                 return out;
460:             }
461:         } else {
462:             // (F44-4) -Local alone: the intake keeps what was sent - said, then confirmed
463:             let id = seen
464:                 .as_ref()
465:                 .map(|p| p.instance_id.clone())
466:                 .or_else(|| crate::telemetry::instance_id_if_exists_in(dir))
467:                 .unwrap_or_default();
468:             out.lines.push(format!(
469:                 "{P}: -Local removes the LOCAL data only - the intake still holds what this machine sent{}; to remove it there, run -Forget -PublicRef <ref> BEFORE -Local (c3 telemetry --forget --public-ref <ref>) - the instance id dies with the salt.",
470:                 if id.is_empty() { String::new() } else { format!(" (instance {id})") }
471:             ));
472:             if !req.yes && !confirm("remove locally? [y/N] ") {
473:                 out.exit = 1;
474:                 out.lines.push(format!(
475:                     "{P}: nothing removed (no confirmation; -Yes removes without asking)."
476:                 ));
477:                 return out;
478:             }
479:         }
480:     }
481:     out.confirmed = true;
482:     // (F09-2) the sender lock and the spool lock for the whole forget: no sender passes its
483:     // deletion check and no producer appends while the transaction is written, the intake asked
484:     // and the local files removed
485:     let Ok(Some(_sender)) = lock_within(&dir.join(FLUSH_LOCK), Duration::from_secs(10)) else {
486:         out.exit = 1;
487:         out.lines.push(format!(
488:             "{P}: {nothing} - another flush is running (its lock is held); try again when it is done."
489:         ));
490:         return out;
491:     };
492:     let Ok(Some(_spool)) = lock_within(&dir.join(SPOOL_LOCK), Duration::from_secs(5)) else {
493:         out.exit = 1;
494:         out.lines.push(format!(
495:             "{P}: {nothing} - the spool lock stayed busy for 5 s; try again."
496:         ));
497:         return out;
498:     };
499:     // the transaction as it is NOW
500:     let current = pending_deletion_in(dir);
501:     if let Some(txn) = current.as_ref().filter(|t| t.cleanup_due()) {
502:         // (F09-3) a confirmed deletion whose local cleanup did not finish: only that is left
503:         out.instance_id = txn.instance_id.clone();
504:         out.public_ref = Some(txn.public_ref.clone()).filter(|r| !r.is_empty());
505:         out.lines.push(format!(
506:             "{P}: finishing the local deletion of {} ({}) - nothing more is asked of the intake.",
507:             instance_label(&txn.instance_id),
508:             if txn.public_ref.is_empty() {
509:                 "a local-only deletion that did not finish".to_string()
510:             } else {
511:                 format!("the intake confirmed its deletion; the local cleanup did not finish (phase {})", txn.phase)
512:             }
513:         ));
514:         finish_cleanup(&mut out, dir, txn, true, remove);
515:         return out;
516:     }
517:     if resume {
518:         // finished by another process meanwhile
519:         out.exit = 0;
520:         out.lines.push(format!(
521:             "{P}: the local deletion was finished meanwhile (by a flush or another forget); nothing left to do."
522:         ));
523:         return out;
524:     }
525:     // the identity: the pending deletion's (the one already asked for), else this salt's
526:     let reference = explicit.or_else(|| pending_ref(&current));
527:     let instance_id = current
528:         .as_ref()
529:         .map(|p| p.instance_id.clone())
530:         .or_else(|| crate::telemetry::instance_id_if_exists_in(dir))
531:         .unwrap_or_default();
532:     out.instance_id = instance_id.clone();
533:     out.public_ref = reference.clone();
534:     let Some(r) = reference else {
535:         // -Local alone: a pending deletion keeps its record (the retry's identity); otherwise the
536:         // cleanup is its own local-only transaction
537:         match current {
538:             Some(p) => {
539:                 finish_cleanup(&mut out, dir, &p, false, remove);
540:                 if pending_deletion_in(dir).is_some() {
541:                     out.pending = true;
542:                     out.lines.push(format!("{P}: the pending deletion of instance {} at the intake is kept ({}): c3 forget-me retries it; until the intake confirms, nothing is spooled or sent.", p.instance_id, dir.join(FORGET_PENDING).display()));
543:                 }
544:             }
545:             None => {
546:                 // (F14-1) the local-only transaction is RECORDED, `cleaning`, before the first
547:                 // removal: an interruption leaves the record that blocks spooling and sending and
548:                 // that the next flush or forget resumes with this identity
549:                 let txn = PendingDeletion {
550:                     instance_id,
551:                     public_ref: String::new(),
552:                     since: now_rfc3339(),
553:                     attempts: 0,
554:                     last_error: String::new(),
555:                     phase: PHASE_CLEANING.to_string(),
556:                 };
557:                 if let Err(e) = write_transaction(dir, &txn) {
558:                     out.exit = 1;
559:                     out.lines.push(format!(
560:                         "{P}: {nothing} - the local deletion could not be recorded before its cleanup ({e})."
561:                     ));
562:                     return out;
563:                 }
564:                 finish_cleanup(&mut out, dir, &txn, true, remove);
565:             }
566:         }
567:         return out;
568:     };
569:     if instance_id.is_empty() {
570:         out.exit = 1;
571:         out.lines.push(format!(
572:             "{P}: this machine has no instance id (no salt {}): the intake holds nothing of it; {nothing}{}.",
573:             dir.join("salt").display(),
574:             if req.local { " (-Forget -Local alone removes the local files)" } else { "" }
575:         ));
576:         return out;
577:     }
578:     // (F09-3) the transaction BEFORE the remote call: a process that dies during or after the DELETE
579:     // leaves a pending deletion that blocks spooling and sending until a retry is confirmed
580:     let mut txn = PendingDeletion {
581:         instance_id: instance_id.clone(),
582:         public_ref: r.clone(),
583:         since: current
584:             .as_ref()
585:             .map(|p| p.since.clone())
586:             .unwrap_or_else(now_rfc3339),
587:         attempts: current.as_ref().map(|p| p.attempts).unwrap_or(0) + 1,
588:         last_error: current
589:             .as_ref()
590:             .map(|p| p.last_error.clone())
591:             .unwrap_or_default(),
592:         phase: PHASE_PENDING.to_string(),
593:     };
594:     if let Err(e) = write_transaction(dir, &txn) {
595:         out.exit = 1;
596:         out.lines.push(format!(
597:             "{P}: {nothing} - the deletion could not be recorded before asking the intake ({e})."
598:         ));
599:         return out;
600:     }
601:     out.pending = true;
